26	            throws DailyOwnerLimitException {
27	        LocalDate effective = request.getRegistrationDate();
28	        if (effective == null) {
29	            effective = LocalDate.now();
30	        }
31	        // Count owners against the same adjusted business day BuildOwner will stamp on this owner,
32	        // so a weekend create is bucketed with the Monday it rolls forward to.
33	        LocalDate businessDay = BusinessDay.rollForward(effective);
34	        long createdThatDay = ownerRepository.findAll().stream()
35	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
36	                .count();
37	        if (createdThatDay >= DAILY_LIMIT) {
38	            throw new DailyOwnerLimitException(createdThatDay);
